<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigWriteGateway;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Connector\Pdo\TenantConfigPdoConnector;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigSlide;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigCursor;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigFilter;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\TenantConfigRef;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\TenantConfig;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class TenantConfigWriteRepositoryAdapter implements TenantConfigWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TenantConfigPdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(TenantConfigRef $ref): ?TenantConfig
    {
        return $this->conn->retrieveForUpdate(new TenantConfigFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?TenantConfigFilter $filter = null, ?TenantConfigCursor $cursor = null): TenantConfigSlide
    {
        $this->logDebug("List for update of Tenant config on adapter ");
        $span = $this->startSpan("List for update of Tenant config on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new TenantConfigSlide(function (TenantConfigSlide $slide, ?TenantConfigCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new TenantConfigCursor($cursor?->limit() ?? 100, $last->uid ?? null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(TenantConfigFilter $filter): ?TenantConfig
    {
        $this->logDebug("Retrieve for update of Tenant config on adapter ");
        $span = $this->startSpan("Retrieve for update of Tenant config on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(?TenantConfigFilter $filter): bool
    {
        $this->logDebug("Exists for update of Tenant config on adapter ");
        $span = $this->startSpan("Exists for update of Tenant config on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?TenantConfigFilter $filter = null): int
    {
        $this->logDebug("Count for update of Tenant config on adapter ");
        $span = $this->startSpan("Count for update of Tenant config on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(TenantConfig $entity, ?Closure $verify = null): TenantConfig
    {
        $this->logDebug("Count for Tenant config on adapter ");
        $span = $this->startSpan("Count for Tenant config on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('tenant-config', $entity->uid(), $entity->asPublicJson(), []);
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(TenantConfigRef $ref, TenantConfig $entity): TenantConfig
    {
        $this->logDebug("Count for Tenant config on adapter ");
        $span = $this->startSpan("Count for Tenant config on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $original = ($reference instanceof TenantConfig) ? $reference : $this->conn->retrieve(new TenantConfigFilter(uids: [ $ref->uid() ]));
            \assert($original !== null);
            $this->changelog->recordChange('tenant-config', $entity->uid(), $entity->asPublicJson(), $original->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(TenantConfig $entity): bool
    {
        $this->logDebug("Count for Tenant config on adapter ");
        $span = $this->startSpan("Count for Tenant config on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('tenant-config', $entity->uid(), $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByUid(string $uid): ?TenantConfig
    {
        $this->logDebug("Find on by uid for Tenant config on adapter");
        $span = $this->startSpan("Find on by uid for Tenant config on adapter");
        try {
            return $this->conn->retrieveForUpdate(new TenantConfigFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByTenant(TenantRef $tenant): ?TenantConfig
    {
        $this->logDebug("Find on by tenant for Tenant config on adapter");
        $span = $this->startSpan("Find on by tenant for Tenant config on adapter");
        try {
            return $this->conn->retrieveForUpdate(new TenantConfigFilter(tenant: $tenant));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(TenantConfig $entity): void
    {
        $this->logDebug("Count for Tenant config on adapter ");
        $span = $this->startSpan("Count for Tenant config on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
